export function validateLocale(value){
 if(arguments.length===0)value=DEFAULT_LOCALE;
 if(typeof value!=='string'||!SUPPORTED_LOCALES.includes(value))throw Error('Unsupported company language; choose en or es');
 return value;
}
export function scopeLocale(scope){
 if(!scope||typeof scope!=='object'||Array.isArray(scope))throw Error('Typed operation scope required for language selection');
 return validateLocale(Object.hasOwn(scope,'locale')?scope.locale:DEFAULT_LOCALE);
}
export function t(key,locale=DEFAULT_LOCALE,parameters={}){
 validateLocale(locale);if(typeof key!=='string')throw Error('Localization key must be text');
 const catalog=locale==='es'?spanish:english;
 const template=Object.hasOwn(catalog,key)?catalog[key]:locale==='es'&&Object.hasOwn(walletSpanish,key)?walletSpanish[key]:key;
 return template.replace(/\{([a-zA-Z][a-zA-Z0-9_]*)\}/g,(match,name)=>Object.hasOwn(parameters,name)?String(parameters[name]):match);
}
export function localizedError(error,locale=DEFAULT_LOCALE){return t(typeof error==='string'?error:String(error?.message??error),locale);}
export function languageName(value,locale=DEFAULT_LOCALE){return t('language.'+validateLocale(value),locale);}

const statuses=Object.freeze({queued:'Queued',awaiting_evidence:'In progress',attested:'Result ready',archived:'Archived',cancelled:'Cancelled',pending_review:'Awaiting review',blocked:'Blocked',reserved:'Reserved',confirmed:'Confirmed',refunding:'Refund pending',refunded:'Refunded',refund_failed:'Refund needs review',settled:'Customer settled',active:'Active',paused:'Paused',available:'Available',unavailable:'Unavailable',expired:'Expired',full:'Full',overlap:'Overlap',frozen:'Frozen',disabled:'Disabled',started:'Started'});
export function statusLabel(value,locale=DEFAULT_LOCALE){validateLocale(locale);return Object.hasOwn(statuses,value)?t(statuses[value],locale):String(value);}

// No observer or whole-document text replacement. Mark only application labels.
// Nested form controls, source quotes, JSON, active content and user values are
// deliberately never replaced. Attribute translations cannot become HTML/URLs.
export function translateMarked(root,locale=DEFAULT_LOCALE){
 validateLocale(locale);if(!root?.querySelectorAll)throw Error('Localization root must be a DOM element or document');
 const selector='[data-i18n],[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]';
 const elements=[...(root.matches?.(selector)?[root]:[]),...root.querySelectorAll(selector)];let translated=0;
 for(const element of elements){
  if(element.closest('script,style,pre,code,template,[contenteditable],[data-i18n-literal]'))continue;
  const key=element.getAttribute('data-i18n');
  if(key!==null&&element.childElementCount===0&&!['INPUT','TEXTAREA'].includes(element.tagName)){
   element.textContent=t(key,locale);translated++;
  }
  for(const name of ['placeholder','title','aria-label']){
   const attributeKey=element.getAttribute('data-i18n-'+name);
   if(attributeKey!==null){element.setAttribute(name,t(attributeKey,locale));translated++;}
  }
 }
 return translated;
}
export function applyDocumentLocale(document,locale=DEFAULT_LOCALE){
 validateLocale(locale);document.documentElement.lang=locale;return translateMarked(document,locale);
}

export function formatDate(value,locale=DEFAULT_LOCALE,options={}){
 validateLocale(locale);
 if(!(value instanceof Date)&&!(typeof value==='string'&&value.trim())&&!(typeof value==='number'&&Number.isFinite(value)))throw Error('Choose a valid appointment time.');
 const date=value instanceof Date?value:new Date(value);
 if(!Number.isFinite(date.getTime()))throw Error('Choose a valid appointment time.');
 const defaults=Object.hasOwn(options,'dateStyle')||Object.hasOwn(options,'timeStyle')?{}:{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'};
 return new Intl.DateTimeFormat(tags[locale],{...defaults,...options}).format(date);
}
function formatUnits(value,decimals,locale,error){
 validateLocale(locale);if(typeof value!=='string'||!/^(0|[1-9]\d{0,38})$/.test(value))throw Error(error);
 const n=BigInt(value),unit=10n**BigInt(decimals),whole=String(n/unit),fraction=String(n%unit).padStart(decimals,'0').replace(/0+$/,'');
 const separator=new Intl.NumberFormat(tags[locale]).formatToParts(1.1).find(part=>part.type==='decimal').value;
 return whole+(fraction?separator+fraction:'');
}
// Lossless integer formatting only. Locale selection never converts currencies,
// rounds a deposit, changes a yoctoNEAR/nanoUSD value, or estimates an exchange.
export function formatNear(value,locale=DEFAULT_LOCALE){return formatUnits(value,24,locale,'Invalid yoctoNEAR amount.')+' NEAR';}
export function formatUsdNanos(value,locale=DEFAULT_LOCALE){return '$'+formatUnits(value,9,locale,'Invalid USD nanos amount.')+' USD';}

function browserStorage(){try{return globalThis.localStorage;}catch{return null;}}
function readPreference(storage,key){try{const value=storage?.getItem(key);return SUPPORTED_LOCALES.includes(value)?value:DEFAULT_LOCALE;}catch{return DEFAULT_LOCALE;}}
export function createLocaleContext({storage=browserStorage(),storageKey=LOCALE_STORAGE_KEY,onChange=()=>{}}={}){
 let preference=readPreference(storage,storageKey),companyId=null,companyLocale=null,epoch=0;
 const locale=()=>companyLocale??preference;
 const snapshot=()=>Object.freeze({locale:locale(),preference,companyId,source:companyId===null?'browser':'company',epoch});
 const update=change=>{const before=snapshot();change();if(before.locale!==locale()||before.companyId!==companyId){epoch++;onChange(snapshot(),before);}return snapshot();};
 return Object.freeze({
  get locale(){return locale();},get companyId(){return companyId;},get epoch(){return epoch;},get preference(){return preference;},
  snapshot,
  setPreference(value){validateLocale(value);return update(()=>{preference=value;try{storage?.setItem(storageKey,value);}catch{/* A blocked local store does not change company authority. */}});},
  bindCompany(id,value=DEFAULT_LOCALE){
   if(typeof id!=='string'||!id.trim())throw Error('Company identity required for language selection');validateLocale(value);
   return update(()=>{companyId=id;companyLocale=value;});
  },
  clearCompany(){return update(()=>{companyId=null;companyLocale=null;});},
  capture(){return Object.freeze({locale:locale(),companyId,epoch});},
  isCurrent(ticket){return !!ticket&&ticket.epoch===epoch&&ticket.companyId===companyId&&ticket.locale===locale();},
 });
}
